    uid: number;
    url: any;
    format: any;
    fetcher: any;
    parser: any;
    isVectorSource: boolean;
    networkOptions: any;
    attribution: any;
    /** @type {Promise<any>} */
    whenReady: Promise<any>;
    _featuresCaches: {};
    extent: any;
    handlingError(err: any): void;
